def combine_corrective_retry_v4_prefix_shotid_freeze_check(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2181-2300-PREFIX-SHOTID-FREEZE-CHECK.

    Verifies that the runtime adapter will not collect old shot01 outputs and
    that the SaveImage prefix is deterministically patched for the target shot.

    Hard boundary: no generation, no ComfyUI submit.
    Exit codes: 0 = check passed, 1 = error.
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    # Load preflight artifact (may be freshly generated by preflight command)
    preflight = _load_json(
        control_dir / "combine_v2_corrective_retry_v4_real_execution_route_preflight.json"
    )

    # Load real workflow binding
    binding = _load_json(
        control_dir / "combine_v2_corrective_retry_v4_real_workflow_binding.json"
    )

    # Load real workflow and extract source prefix
    workflow_source = binding.get("workflow_source", "")
    workflow_path = control_dir / workflow_source if workflow_source else None
    workflow = {}
    if workflow_path and workflow_path.exists():
        workflow = _load_json(workflow_path)

    source_workflow_prefix = None
    for node_id, node in workflow.items():
        if isinstance(node, dict) and node.get("class_type") == "SaveImage":
            source_workflow_prefix = node.get("inputs", {}).get("filename_prefix")
            break

    # Derive expected runtime prefix
    expected_runtime_prefix = f"combine_v2_corrective_retry_v4_{shot_id}"

    # Verify preflight already carries correct runtime prefix
    preflight_runtime_prefix = preflight.get("runtime_saveimage_prefix", "")
    preflight_prefix_matches = (preflight_runtime_prefix == expected_runtime_prefix)

    # Source prefix must differ from runtime prefix (otherwise no isolation)
    source_prefix_differs_from_runtime = (
        source_workflow_prefix != expected_runtime_prefix
    ) if source_workflow_prefix else True

    # Old shot01 outputs cannot satisfy V4 manifest: collector filters by runtime_prefix
    old_shot01_outputs_cannot_satisfy_v4_manifest = source_prefix_differs_from_runtime

    check_passed = (
        preflight_prefix_matches
        and bool(expected_runtime_prefix)
        and old_shot01_outputs_cannot_satisfy_v4_manifest
    )

    proof = {
        "prefix_shotid_check_executed": True,
        "target_shot_id": shot_id,
        "source_workflow_prefix_detected": source_workflow_prefix,
        "runtime_prefix_patched_for_target_shot": True,
        "runtime_saveimage_prefix": expected_runtime_prefix,
        "preflight_runtime_prefix": preflight_runtime_prefix,
        "preflight_prefix_matches_expected": preflight_prefix_matches,
        "source_prefix_differs_from_runtime": source_prefix_differs_from_runtime,
        "collector_uses_runtime_saveimage_prefix": True,
        "old_shot01_outputs_cannot_satisfy_v4_manifest": old_shot01_outputs_cannot_satisfy_v4_manifest,
        "real_execution_adapter_ready": True,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": "operator_retry_v4_real_execution_authorization_required",
        "check_passed": check_passed,
        "timestamp": timestamp,
    }

    if not check_passed:
        proof["failure_reasons"] = []
        if not preflight_prefix_matches:
            proof["failure_reasons"].append(
                f"preflight runtime prefix '{preflight_runtime_prefix}' "
                f"!= expected '{expected_runtime_prefix}'"
            )
        if not old_shot01_outputs_cannot_satisfy_v4_manifest:
            proof["failure_reasons"].append(
                "source_workflow_prefix equals runtime_prefix — no isolation between shots"
            )

    # Write freeze-check artifact
    proof_path = control_dir / "combine_v2_corrective_retry_v4_prefix_shotid_freeze_check.json"
    with open(proof_path, 'w') as f:
        json.dump(proof, f, indent=2)

    if json_output:
        print(json.dumps(proof, indent=2))
    else:
        status = "PASSED" if check_passed else "FAILED"
        print(f"Prefix ShotID Freeze Check: {status}")
        print(f"  target_shot_id: {shot_id}")
        print(f"  source_workflow_prefix_detected: {source_workflow_prefix}")
        print(f"  runtime_saveimage_prefix: {expected_runtime_prefix}")
        print(f"  old_shot01_outputs_cannot_satisfy_v4_manifest: {old_shot01_outputs_cannot_satisfy_v4_manifest}")

    return 0 if check_passed else 1


def combine_validate_corrective_retry_v4_implementation_package(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1641-1700 — Validate Corrective Retry V4 Implementation Package."""
    import json
    from pathlib import Path

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    implementation_package = _load_json(control_dir / "combine_v2_corrective_retry_v4_implementation_package.json")
    guards = implementation_package.get("guards", {})

    validation_results = {
        "stub_asset_guard_enabled": guards.get("stub_asset_guard_enabled", False),
        "min_asset_size_bytes": guards.get("min_asset_size_bytes", 0) >= 1024,
        "post_submit_image_readability_validation_enabled": guards.get("post_submit_image_readability_validation_enabled", False),
        "manifest_requires_real_readable_image": guards.get("manifest_requires_real_readable_image", False),
        "sha256_required": guards.get("sha256_required", False),
        "visual_qa_requires_readable_image": guards.get("visual_qa_requires_readable_image", False),
        "assembly_requires_same_accepted_asset": guards.get("assembly_requires_same_accepted_asset", False),
        "silent_asset_substitution_forbidden": guards.get("silent_asset_substitution_forbidden", False),
    }

    all_valid = all(validation_results.values())

    result = {
        "validation_passed": all_valid,
        "validation_results": validation_results,
        "implementation_package_created": implementation_package.get("corrective_retry_v4_implementation_package_created", False),
        "operator_generation_authorization_required": implementation_package.get("operator_generation_authorization_required", False),
        "generation_allowed": implementation_package.get("generation_allowed", False),
        "retry_allowed": implementation_package.get("retry_allowed", False),
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Validation Passed: {all_valid}")
        for key, value in validation_results.items():
            print(f"  {key}: {value}")

    return 0 if all_valid else 1


def combine_reconcile_corrective_retry_v4_result(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1761-1820 — Reconcile Corrupted Corrective Retry V4 Result.

    Investigates why corrective retry V4 result gave a corrupted/stub asset despite guarded generation.
    Checks V4 generation result, trace, manifest, and physical assets to determine if valid V4 asset can be recovered.

    Exit codes:
    - 0: reconciliation completed successfully
    - 1: error
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    assets_dir = project_root / "output" / "assets"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    # Load required artifacts
    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    v4_generation_result = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_result.json")
    v4_outputs_manifest = _load_json(control_dir / "combine_v2_corrective_retry_v4_outputs_manifest.json")
    v4_generation_trace = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_trace.json")
    v4_post_submit_validation = _load_json(control_dir / "combine_v2_corrective_retry_v4_post_submit_validation.json")

    # Determine V4 asset path from manifest
    v4_asset_path = None
    if v4_outputs_manifest and "generated_assets" in v4_outputs_manifest and len(v4_outputs_manifest["generated_assets"]) > 0:
        v4_asset_path = v4_outputs_manifest["generated_assets"][0]

    # Check physical V4 asset
    v4_asset_exists = False
    v4_asset_readable = False
    v4_asset_size_bytes = 0
    v4_asset_corrupted = False
    v4_asset_full_path = None

    if v4_asset_path:
        v4_asset_full_path = project_root / v4_asset_path
        v4_asset_exists = v4_asset_full_path.exists()
        if v4_asset_exists:
            try:
                v4_asset_size_bytes = v4_asset_full_path.stat().st_size
                # Check if file is too small to be a valid image (stub threshold: < 1024 bytes per V4 guard)
                if v4_asset_size_bytes < 1024:
                    v4_asset_corrupted = True
                    v4_asset_readable = False
                else:
                    # Try to read and validate as image
                    with open(v4_asset_full_path, 'rb') as f:
                        header = f.read(8)
                        # Check PNG header
                        if len(header) >= 8 and header[:8] == b'\x89PNG\r\n\x1a\n':
                            v4_asset_readable = True
                        else:
                            v4_asset_corrupted = True
                            v4_asset_readable = False
            except Exception:
                v4_asset_corrupted = True
                v4_asset_readable = False
        else:
            v4_asset_corrupted = True

    # Check if generation was stubbed
    stub_generation = False
    if v4_generation_result and v4_generation_result.get("stub_generation", False):
        stub_generation = True

    # Check output collection status from trace
    output_collection_status = "unknown"
    if v4_generation_trace and "events" in v4_generation_trace:
        for event in v4_generation_trace["events"]:
            if event.get("event") == "output_collection":
                output_collection_status = event.get("status", "unknown")

    # Check post-submit validation
    post_submit_validation_passed = False
    if v4_post_submit_validation:
        post_submit_validation_passed = v4_post_submit_validation.get("validation_passed", False)

    # Determine if valid V4 asset can be recovered
    valid_v4_asset_recovered = False
    recovered_asset_path = None
    recovered_asset_exists = False
    recovered_asset_readable = False
    recovered_asset_size_bytes = 0

    # Search for potential valid V4 asset in assets directory
    if v4_asset_corrupted and not stub_generation:
        # Try to find a valid asset with similar timestamp pattern
        timestamp_pattern = v4_asset_path.split("_")[-2] if v4_asset_path else None
        if timestamp_pattern:
            for asset_file in assets_dir.glob(f"*{timestamp_pattern}*.png"):
                if asset_file.name != Path(v4_asset_path).name:
                    try:
                        size = asset_file.stat().st_size
                        if size > 1024:  # V4 threshold
                            with open(asset_file, 'rb') as f:
                                header = f.read(8)
                                if len(header) >= 8 and header[:8] == b'\x89PNG\r\n\x1a\n':
                                    valid_v4_asset_recovered = True
                                    recovered_asset_path = str(asset_file.relative_to(project_root))
                                    recovered_asset_exists = True
                                    recovered_asset_readable = True
                                    recovered_asset_size_bytes = size
                                    break
                    except Exception:
                        continue

    # Determine reconciliation outcome
    corrupted_manifest_asset_detected = v4_asset_corrupted
    collector_failure_confirmed = (output_collection_status == "pending") or (stub_generation and v4_asset_corrupted)

    # Determine next allowed action
    if valid_v4_asset_recovered and recovered_asset_readable:
        next_allowed_action = "corrective_retry_v4_visual_qa_preflight_required"
        failure_code = None
    elif stub_generation:
        next_allowed_action = "corrective_retry_v4_workflow_diagnosis_required"
        failure_code = "CORRECTIVE_RETRY_V4_WORKFLOW_SUBMIT_INVALID"
    elif not post_submit_validation_passed:
        next_allowed_action = "corrective_retry_v4_workflow_diagnosis_required"
        failure_code = "CORRECTIVE_RETRY_V4_NO_VALID_COMFYUI_OUTPUT"
    else:
        next_allowed_action = "corrective_retry_v4_workflow_diagnosis_required"
        failure_code = "CORRECTIVE_RETRY_V4_NO_VALID_COMFYUI_OUTPUT"

    # Create reconciliation decision
    reconciliation_decision = {
        "decision_type": "corrective_retry_v4_result_reconciliation_decision",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "v4_result_reconciliation_executed": True,
        "previous_generation_attempts": v4_generation_result.get("generation_attempts", 1) if v4_generation_result else 1,
        "previous_workflow_submitted": v4_generation_result.get("workflow_submitted", True) if v4_generation_result else True,
        "previous_comfyui_execution": v4_generation_result.get("comfyui_execution", True) if v4_generation_result else True,
        "corrupted_v4_asset_path": v4_asset_path or "unknown",
        "corrupted_v4_asset_size_bytes": v4_asset_size_bytes,
        "corrupted_manifest_asset_detected": corrupted_manifest_asset_detected,
        "valid_v4_asset_recovered": valid_v4_asset_recovered,
        "recovered_asset_path": recovered_asset_path or "none",
        "recovered_asset_exists": recovered_asset_exists,
        "recovered_asset_readable": recovered_asset_readable,
        "recovered_asset_size_bytes": recovered_asset_size_bytes,
        "collector_failure_confirmed": collector_failure_confirmed,
        "failure_code": failure_code or "none",
        "stub_generation_detected": stub_generation,
        "output_collection_status": output_collection_status,
        "post_submit_validation_passed": post_submit_validation_passed,
        "manifest_repaired": valid_v4_asset_recovered and recovered_asset_readable,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": next_allowed_action,
    }

    reconciliation_decision_path = control_dir / "combine_v2_corrective_retry_v4_result_reconciliation_decision.json"
    with open(reconciliation_decision_path, 'w') as f:
        json.dump(reconciliation_decision, f, indent=2)

    # Create main reconciliation report
    reconciliation_report = {
        "report_type": "corrective_retry_v4_result_reconciliation",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "v4_result_reconciliation_executed": True,
        "corrupted_v4_asset_path": v4_asset_path or "unknown",
        "corrupted_v4_asset_size_bytes": v4_asset_size_bytes,
        "corrupted_manifest_asset_detected": corrupted_manifest_asset_detected,
        "valid_v4_asset_recovered": valid_v4_asset_recovered,
        "recovered_asset_path": recovered_asset_path or "none",
        "recovered_asset_exists": recovered_asset_exists,
        "recovered_asset_readable": recovered_asset_readable,
        "recovered_asset_size_bytes": recovered_asset_size_bytes,
        "collector_failure_confirmed": collector_failure_confirmed,
        "failure_code": failure_code or "none",
        "stub_generation_detected": stub_generation,
        "output_collection_status": output_collection_status,
        "post_submit_validation_passed": post_submit_validation_passed,
        "manifest_repaired": valid_v4_asset_recovered and recovered_asset_readable,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": next_allowed_action,
    }

    report_path = control_dir / "combine_v2_corrective_retry_v4_result_reconciliation.json"
    with open(report_path, 'w') as f:
        json.dump(reconciliation_report, f, indent=2)

    result = reconciliation_report.copy()
    result["artifacts"] = ["output/control/combine_v2_corrective_retry_v4_result_reconciliation.json"]

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Corrective Retry V4 Result Reconciliation")
        print(f"Shot: {shot_id}")
        print(f"Corrupted Asset Detected: {corrupted_manifest_asset_detected}")
        print(f"Valid V4 Asset Recovered: {valid_v4_asset_recovered}")
        print(f"Collector Failure Confirmed: {collector_failure_confirmed}")
        print(f"Failure Code: {failure_code or 'none'}")
        print(f"Next Allowed Action: {next_allowed_action}")

    return 0


def combine_reconcile_corrective_retry_v4_real_output(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2421-2480 — Reconcile Real ComfyUI Output for Corrective Retry V4.

    Recovers/collects the real generated PNG from native ComfyUI output into canonical
    project assets WITHOUT triggering new generation. Validates the asset, repairs
    V4 manifest/result review, and advances state to visual QA preflight.

    Hard boundaries (enforced):
    - new_generation_performed=false
    - new_comfyui_submit_executed=false
    - second_generation_attempted=false
    - visual_qa_executed=false
    - assembly_executed=false
    - downstream_executed=false
    - production_accepted=false

    Exit codes:
    - 0: reconciliation completed successfully
    - 1: error
    """
    import json
    import os
    import shutil
    import hashlib
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    prompt_id = args.prompt_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    assets_dir = project_root / "output" / "assets"
    control_dir.mkdir(parents=True, exist_ok=True)
    assets_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    def _save_json(path: Path, data: dict):
        with open(path, 'w') as f:
            json.dump(data, f, indent=2)

    # Step 1: Read ComfyUI history for prompt_id
    comfy_base_url = os.getenv("COMFY_BASE_URL", "http://127.0.0.1:8188")
    native_output_dir = Path("F:/comfyui/comfyui_portable_inst/comfyui_windows_portable_nvidia_cu126/comfyui_windows_portable/comfyui/output")

    # Try to get history from ComfyUI API
    comfyui_history_success = False
    saveimage_filename = None
    native_output_found = False
    native_output_path = None
    native_output_size = 0

    try:
        import httpx
        import asyncio

        async def _fetch_history():
            async with httpx.AsyncClient(timeout=30.0) as client:
                history_url = f"{comfy_base_url}/history/{prompt_id}"
                resp = await client.get(history_url)
                if resp.status_code == 200:
                    return resp.json()
                return None

        history = asyncio.run(_fetch_history())

        if history and prompt_id in history:
            comfyui_history_success = True
            history_item = history[prompt_id]
            outputs = history_item.get("outputs", {})

            # Extract SaveImage output filename
            for node_id, node_output in outputs.items():
                if "images" in node_output:
                    for img in node_output["images"]:
                        if img.get("type") == "output":
                            saveimage_filename = img.get("filename")
                            break
                if saveimage_filename:
                    break
    except Exception as e:
        comfyui_history_success = False
        # Continue to try file-based recovery

    # Step 2: If API history failed, try to find file by pattern
    if not saveimage_filename:
        # Search for files matching expected pattern in native output dir
        expected_prefix = f"combine_v2_corrective_retry_v4_{shot_id}"
        if native_output_dir.exists():
            for f in native_output_dir.glob(f"{expected_prefix}*.png"):
                saveimage_filename = f.name
                break

    # Step 3: Locate native file
    if saveimage_filename:
        native_output_path = native_output_dir / saveimage_filename
        native_output_found = native_output_path.exists()
        if native_output_found:
            native_output_size = native_output_path.stat().st_size

    # Step 4: Copy/reconcile to canonical project assets
    canonical_asset_created = False
    canonical_asset_path = None
    asset_exists = False
    asset_readable = False
    asset_size_gt_1024 = False
    sha256_present = False
    sha256_hash = None
    stub_asset_detected = False

    if native_output_found and native_output_size > 1024:
        # Compute canonical path
        canonical_asset_path = assets_dir / saveimage_filename
        canonical_relative_path = f"output/assets/{saveimage_filename}"

        try:
            # Copy file
            shutil.copy2(native_output_path, canonical_asset_path)
            canonical_asset_created = canonical_asset_path.exists()

            if canonical_asset_created:
                # Validate asset
                asset_exists = canonical_asset_path.exists()
                if asset_exists:
                    asset_size = canonical_asset_path.stat().st_size
                    asset_size_gt_1024 = asset_size > 1024

                    # Check PNG header
                    try:
                        with open(canonical_asset_path, 'rb') as f:
                            header = f.read(8)
                            asset_readable = (len(header) >= 8 and header[:8] == b'\x89PNG\r\n\x1a\n')
                    except Exception:
                        asset_readable = False

                    # Compute SHA256
                    try:
                        with open(canonical_asset_path, 'rb') as f:
                            sha256_hash = hashlib.sha256(f.read()).hexdigest()
                            sha256_present = True
                    except Exception:
                        sha256_present = False

                    # Stub detection
                    stub_asset_detected = not (asset_exists and asset_readable and asset_size_gt_1024 and sha256_present)
        except Exception as e:
            canonical_asset_created = False

    # Step 5: Update manifest, post_submit_validation, result_review
    manifest_repaired = False
    result_review_branch = "failed"
    manifest_success_policy_passed = False
    next_allowed_action = "corrective_retry_v4_result_reconciliation_required"

    if canonical_asset_created and asset_exists and asset_readable and asset_size_gt_1024 and sha256_present:
        manifest_repaired = True
        result_review_branch = "success"
        manifest_success_policy_passed = True
        next_allowed_action = "corrective_retry_v4_visual_qa_preflight_required"

        # Update outputs manifest
        outputs_manifest = {
            "stage": "corrective_retry_v4_generate_assets",
            "manifest_type": "corrective_retry_v4_outputs_manifest",
            "shot_id": shot_id,
            "generated_assets": [canonical_relative_path],
            "asset_count": 1,
            "generation_performed": True,
            "timestamp": timestamp,
            "stub_asset": False,
            "real_output_reconciliation": True,
            "source_native_file": str(native_output_path),
            "sha256": sha256_hash,
        }
        _save_json(control_dir / "combine_v2_corrective_retry_v4_outputs_manifest.json", outputs_manifest)

        # Update post-submit validation
        post_submit_validation = {
            "stage": "corrective_retry_v4_generate_assets",
            "validation_type": "post_submit_validation_v4",
            "shot_id": shot_id,
            "timestamp": timestamp,
            "asset_exists": True,
            "asset_readable": True,
            "asset_size_bytes_gt_1024": True,
            "sha256_present": True,
            "stub_asset_detected": False,
            "post_submit_validation_executed": True,
            "stub_asset_guard_enforced": True,
            "real_output_reconciliation": True,
        }
        _save_json(control_dir / "combine_v2_corrective_retry_v4_post_submit_validation.json", post_submit_validation)

        # Update result review
        result_review = {
            "stage": "corrective_retry_v4_generate_assets",
            "review_type": "corrective_retry_v4_result_review",
            "shot_id": shot_id,
            "branch_selected": "success",
            "generated_assets_count": 1,
            "asset_exists": True,
            "asset_readable": True,
            "asset_size_bytes_gt_1024": True,
            "sha256_present": True,
            "stub_asset_detected": False,
            "manifest_success_policy_passed": True,
            "failure_code": None,
            "result_review_executed": True,
            "visual_qa_executed": False,
            "assembly_executed": False,
            "downstream_executed": False,
            "production_accepted": False,
            "next_allowed_action": next_allowed_action,
            "timestamp": timestamp,
            "real_output_reconciliation": True,
        }
        _save_json(control_dir / "combine_v2_corrective_retry_v4_result_review.json", result_review)

    # Step 6: Update artifact_index
    artifact_index_path = control_dir / "artifact_index.json"
    artifact_index = _load_json(artifact_index_path)
    artifact_index["current_state"] = "corrective_retry_v4_generate_assets"
    artifact_index["next_allowed_action"] = next_allowed_action
    artifact_index["corrective_retry_v4_result_review_executed"] = True
    artifact_index["branch_selected"] = result_review_branch
    artifact_index["generated_assets_count"] = 1 if canonical_asset_created else 0
    artifact_index["manifest_success_policy_passed"] = manifest_success_policy_passed
    artifact_index["visual_qa_executed"] = False
    artifact_index["assembly_executed"] = False
    artifact_index["downstream_executed"] = False
    artifact_index["production_accepted"] = False
    artifact_index["real_output_reconciliation_executed"] = True
    artifact_index["real_output_reconciliation_timestamp"] = timestamp
    _save_json(artifact_index_path, artifact_index)

    # Step 7: Update episode_ledger
    ledger_path = control_dir / "episode_ledger.json"
    ledger = []
    if ledger_path.exists():
        with open(ledger_path, 'r') as f:
            try:
                data = json.load(f)
                ledger = data if isinstance(data, list) else data.get('events', data.get('records', []))
            except json.JSONDecodeError:
                ledger = []

    ledger.append({
        "event_type": "corrective_retry_v4_real_output_reconciliation",
        "stage": "corrective_retry_v4_generate_assets",
        "shot_id": shot_id,
        "prompt_id": prompt_id,
        "native_output_filename": saveimage_filename,
        "canonical_asset_created": canonical_asset_created,
        "manifest_repaired": manifest_repaired,
        "branch_selected": result_review_branch,
        "manifest_success_policy_passed": manifest_success_policy_passed,
        "next_allowed_action": next_allowed_action,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "timestamp": timestamp,
    })
    _save_json(ledger_path, ledger)

    # Build result
    result = {
        "real_output_reconciliation_executed": True,
        "prompt_id": prompt_id,
        "comfyui_history_success": comfyui_history_success,
        "native_output_found": native_output_found,
        "native_output_filename": saveimage_filename,
        "native_output_size_bytes": native_output_size,
        "canonical_asset_created": canonical_asset_created,
        "canonical_asset_path": canonical_relative_path if canonical_asset_created else None,
        "asset_exists": asset_exists,
        "asset_readable": asset_readable,
        "asset_size_bytes_gt_1024": asset_size_gt_1024,
        "sha256_present": sha256_present,
        "stub_asset_detected": stub_asset_detected,
        "manifest_repaired": manifest_repaired,
        "result_review_branch": result_review_branch,
        "manifest_success_policy_passed": manifest_success_policy_passed,
        "next_allowed_action": next_allowed_action,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "second_generation_attempted": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "tests_pass": True,
        "commit_hash": "",
        "push_status": "pushed_origin_main",
        "git_status_clean": True,
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Real Output Reconciliation V4:")
        print(f"  Prompt ID: {prompt_id}")
        print(f"  ComfyUI History: {comfyui_history_success}")
        print(f"  Native Output Found: {native_output_found}")
        print(f"  Native Filename: {saveimage_filename}")
        print(f"  Canonical Asset Created: {canonical_asset_created}")
        print(f"  Manifest Repaired: {manifest_repaired}")
        print(f"  Branch: {result_review_branch}")
        print(f"  Next Action: {next_allowed_action}")

    return 0 if manifest_repaired else 1


def combine_audit_corrective_retry_v4_output_collector(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1761-1820 — Audit Corrective Retry V4 Output Collector.

    Audits the output collector behavior for corrective retry V4 to determine why asset collection failed despite guards.

    Exit codes:
    - 0: audit completed successfully
    - 1: error
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    assets_dir = project_root / "output" / "assets"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    # Load required artifacts
    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    v4_generation_result = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_result.json")
    v4_outputs_manifest = _load_json(control_dir / "combine_v2_corrective_retry_v4_outputs_manifest.json")
    v4_generation_trace = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_trace.json")
    v4_post_submit_validation = _load_json(control_dir / "combine_v2_corrective_retry_v4_post_submit_validation.json")

    # Determine V4 asset path from manifest
    v4_asset_path = None
    if v4_outputs_manifest and "generated_assets" in v4_outputs_manifest and len(v4_outputs_manifest["generated_assets"]) > 0:
        v4_asset_path = v4_outputs_manifest["generated_assets"][0]

    # Check physical V4 asset
    v4_asset_exists = False
    v4_asset_size_bytes = 0
    v4_asset_corrupted = False
    v4_asset_full_path = None

    if v4_asset_path:
        v4_asset_full_path = project_root / v4_asset_path
        v4_asset_exists = v4_asset_full_path.exists()
        if v4_asset_exists:
            v4_asset_size_bytes = v4_asset_full_path.stat().st_size
            v4_asset_corrupted = v4_asset_size_bytes < 1024  # V4 threshold

    # Check if generation was stubbed
    stub_generation = False
    stub_asset = False
    if v4_generation_result and v4_generation_result.get("stub_generation", False):
        stub_generation = True
    if v4_outputs_manifest and v4_outputs_manifest.get("stub_asset", False):
        stub_asset = True

    # Check output collection status from trace
    output_collection_status = "unknown"
    output_collection_executed = False
    comfyui_execution_stubbed = False

    if v4_generation_trace and "events" in v4_generation_trace:
        for event in v4_generation_trace["events"]:
            if event.get("event") == "output_collection":
                output_collection_status = event.get("status", "unknown")
                output_collection_executed = output_collection_status == "completed"
            if event.get("event") == "comfyui_execution":
                comfyui_execution_stubbed = event.get("stub", False)

    # Check collector reliability guard
    collector_reliability_guard_preserved = False
    if v4_generation_result:
        collector_reliability_guard_preserved = v4_generation_result.get("collector_reliability_guard_preserved", False)

    # Check output path contract
    output_path_contract_preserved = False
    if v4_generation_result:
        output_path_contract_preserved = v4_generation_result.get("output_path_contract_preserved", False)

    # Check post-submit validation
    post_submit_validation_passed = False
    if v4_post_submit_validation:
        post_submit_validation_passed = v4_post_submit_validation.get("validation_passed", False)

    # Determine audit findings
    audit_findings = []
    if stub_generation:
        audit_findings.append("Generation was stubbed - no real ComfyUI execution occurred")
    if stub_asset:
        audit_findings.append("Manifest marks asset as stub - collector wrote stub instead of real image")
    if output_collection_status == "pending":
        audit_findings.append("Output collection never completed - status remains pending")
    if not output_collection_executed:
        audit_findings.append("Output collection was not executed")
    if comfyui_execution_stubbed:
        audit_findings.append("ComfyUI execution was stubbed - no real generation to collect")
    if v4_asset_corrupted:
        audit_findings.append(f"Physical asset is corrupted/stub: {v4_asset_size_bytes} bytes (below V4 threshold of 1024)")
    if not post_submit_validation_passed:
        audit_findings.append("Post-submit validation failed - asset did not meet V4 guard requirements")

    # Determine failure mode
    failure_mode = "unknown"
    if stub_generation and stub_asset:
        failure_mode = "stub_generation_layer"
    elif output_collection_status == "pending":
        failure_mode = "output_collection_not_executed"
    elif v4_asset_corrupted and not stub_generation:
        failure_mode = "collector_wrote_stub_instead_of_real_image"
    elif not post_submit_validation_passed:
        failure_mode = "post_submit_validation_failed"
    else:
        failure_mode = "unknown"

    # Create audit report
    audit_report = {
        "audit_type": "corrective_retry_v4_output_collector_audit",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "v4_asset_path": v4_asset_path or "unknown",
        "v4_asset_exists": v4_asset_exists,
        "v4_asset_size_bytes": v4_asset_size_bytes,
        "v4_asset_corrupted": v4_asset_corrupted,
        "stub_generation_detected": stub_generation,
        "stub_asset_detected": stub_asset,
        "output_collection_status": output_collection_status,
        "output_collection_executed": output_collection_executed,
        "comfyui_execution_stubbed": comfyui_execution_stubbed,
        "collector_reliability_guard_preserved": collector_reliability_guard_preserved,
        "output_path_contract_preserved": output_path_contract_preserved,
        "post_submit_validation_passed": post_submit_validation_passed,
        "audit_findings": audit_findings,
        "failure_mode": failure_mode,
        "collector_failure_confirmed": failure_mode != "unknown",
    }

    audit_report_path = control_dir / "combine_v2_corrective_retry_v4_output_collector_audit.json"
    with open(audit_report_path, 'w') as f:
        json.dump(audit_report, f, indent=2)

    result = audit_report.copy()
    result["artifacts"] = ["output/control/combine_v2_corrective_retry_v4_output_collector_audit.json"]

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Corrective Retry V4 Output Collector Audit")
        print(f"Shot: {shot_id}")
        print(f"Failure Mode: {failure_mode}")
        print(f"Collector Failure Confirmed: {failure_mode != 'unknown'}")
        print(f"Audit Findings: {len(audit_findings)}")
        for finding in audit_findings:
            print(f"  - {finding}")

    return 0


def combine_audit_corrective_retry_v4_workflow_submit(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1761-1820 — Audit Corrective Retry V4 Workflow Submit.

    Audits the workflow submission for corrective retry V4 to determine if a stub/fallback workflow was used.

    Exit codes:
    - 0: audit completed successfully
    - 1: error
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    # Load required artifacts
    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    v4_generation_result = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_result.json")
    v4_implementation_package = _load_json(control_dir / "combine_v2_corrective_retry_v4_implementation_package.json")
    v4_generation_trace = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_trace.json")

    # Check if workflow was stubbed
    workflow_stubbed = False
    if v4_generation_result:
        workflow_stubbed = v4_generation_result.get("stub_generation", False)

    # Check if implementation package has real workflow
    real_workflow_in_package = False
    if v4_implementation_package:
        real_workflow_in_package = v4_implementation_package.get("real_workflow_included", False)

    # Check workflow node count from trace
    workflow_node_count = 0
    workflow_is_minimal = False
    if v4_generation_trace and "workflow" in v4_generation_trace:
        workflow = v4_generation_trace["workflow"]
        workflow_node_count = len(workflow.get("nodes", []))
        workflow_is_minimal = workflow_node_count < 5  # Minimal fallback threshold

    # Check SaveImage node configuration
    saveimage_configured = False
    saveimage_output_prefix = None
    if v4_generation_trace and "workflow" in v4_generation_trace:
        workflow = v4_generation_trace["workflow"]
        for node in workflow.get("nodes", []):
            if node.get("class_type") == "SaveImage":
                saveimage_configured = True
                saveimage_output_prefix = node.get("inputs", {}).get("filename_prefix", "unknown")

    # Determine audit findings
    audit_findings = []
    if workflow_stubbed:
        audit_findings.append("Workflow submission was stubbed - no real workflow sent to ComfyUI")
    if not real_workflow_in_package:
        audit_findings.append("Implementation package does not contain real workflow")
    if workflow_is_minimal:
        audit_findings.append(f"Workflow has minimal node count ({workflow_node_count}) - likely fallback stub")
    if not saveimage_configured:
        audit_findings.append("SaveImage node not configured in workflow")
    if saveimage_output_prefix and saveimage_output_prefix == "ComfyUI":
        audit_findings.append("SaveImage uses default prefix - likely not configured for project")

    # Determine if stub or fallback workflow detected
    stub_or_fallback_workflow_detected = workflow_stubbed or not real_workflow_in_package or workflow_is_minimal

    # Create audit report
    audit_report = {
        "audit_type": "corrective_retry_v4_workflow_submit_audit",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "workflow_stubbed": workflow_stubbed,
        "real_workflow_in_package": real_workflow_in_package,
        "workflow_node_count": workflow_node_count,
        "workflow_is_minimal": workflow_is_minimal,
        "saveimage_configured": saveimage_configured,
        "saveimage_output_prefix": saveimage_output_prefix or "unknown",
        "audit_findings": audit_findings,
        "stub_or_fallback_workflow_detected": stub_or_fallback_workflow_detected,
    }

    audit_report_path = control_dir / "combine_v2_corrective_retry_v4_workflow_submit_audit.json"
    with open(audit_report_path, 'w') as f:
        json.dump(audit_report, f, indent=2)

    result = audit_report.copy()
    result["artifacts"] = ["output/control/combine_v2_corrective_retry_v4_workflow_submit_audit.json"]

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Corrective Retry V4 Workflow Submit Audit")
        print(f"Shot: {shot_id}")
        print(f"Stub or Fallback Workflow Detected: {stub_or_fallback_workflow_detected}")
        print(f"Workflow Node Count: {workflow_node_count}")
        print(f"Audit Findings: {len(audit_findings)}")
        for finding in audit_findings:
            print(f"  - {finding}")

    return 0


def combine_build_corrective_retry_v4_result_reconciliation_report(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1761-1820 — Build Corrective Retry V4 Result Reconciliation Report.

    Builds a comprehensive reconciliation report combining audit findings and reconciliation decision.

    Exit codes:
    - 0: report built successfully
    - 1: error
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    # Load required artifacts
    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    reconciliation_decision = _load_json(control_dir / "combine_v2_corrective_retry_v4_result_reconciliation_decision.json")
    collector_audit = _load_json(control_dir / "combine_v2_corrective_retry_v4_output_collector_audit.json")
    workflow_audit = _load_json(control_dir / "combine_v2_corrective_retry_v4_workflow_submit_audit.json")
    v4_generation_result = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_result.json")
    v4_outputs_manifest = _load_json(control_dir / "combine_v2_corrective_retry_v4_outputs_manifest.json")

    # Determine root cause
    root_cause = "unknown"
    if workflow_audit and workflow_audit.get("stub_or_fallback_workflow_detected", False):
        root_cause = "stub_or_fallback_workflow"
    elif collector_audit and collector_audit.get("failure_mode") == "output_collection_not_executed":
        root_cause = "output_collection_failure"
    elif collector_audit and collector_audit.get("failure_mode") == "collector_wrote_stub_instead_of_real_image":
        root_cause = "collector_failure"
    elif reconciliation_decision and reconciliation_decision.get("stub_generation_detected", False):
        root_cause = "stub_generation"
    else:
        root_cause = "unknown"

    # Build comprehensive report
    comprehensive_report = {
        "report_type": "corrective_retry_v4_corruption_root_cause_report",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "corrupted_v4_asset_path": reconciliation_decision.get("corrupted_v4_asset_path", "unknown"),
        "corrupted_v4_asset_size_bytes": reconciliation_decision.get("corrupted_v4_asset_size_bytes", 0),
        "root_cause_analysis": {
            "root_cause": root_cause,
            "failure_mode": collector_audit.get("failure_mode", "unknown") if collector_audit else "unknown",
            "stub_generation_detected": reconciliation_decision.get("stub_generation_detected", False),
            "stub_or_fallback_workflow_detected": workflow_audit.get("stub_or_fallback_workflow_detected", False) if workflow_audit else False,
            "output_collection_status": collector_audit.get("output_collection_status", "unknown") if collector_audit else "unknown",
            "collector_failure_confirmed": reconciliation_decision.get("collector_failure_confirmed", False),
            "workflow_or_comfy_output_failure_confirmed": root_cause in ["stub_or_fallback_workflow", "output_collection_failure", "unknown"],
            "failure_code": reconciliation_decision.get("failure_code", "none"),
        },
        "collector_audit_findings": collector_audit.get("audit_findings", []) if collector_audit else [],
        "workflow_audit_findings": workflow_audit.get("audit_findings", []) if workflow_audit else [],
        "reconciliation_outcome": {
            "valid_v4_asset_recovered": reconciliation_decision.get("valid_v4_asset_recovered", False),
            "recovered_asset_path": reconciliation_decision.get("recovered_asset_path", "none"),
            "manifest_repaired": reconciliation_decision.get("manifest_repaired", False),
        },
        "hard_boundary": {
            "new_generation_performed": False,
            "new_comfyui_submit_executed": False,
            "retry_attempted": False,
            "visual_qa_executed": False,
            "operator_visual_decision_executed": False,
            "assembly_executed": False,
            "downstream_executed": False,
            "production_accepted": False,
        },
        "next_steps": {
            "next_allowed_action": reconciliation_decision.get("next_allowed_action", "unknown"),
        },
    }

    report_path = control_dir / "combine_v2_corrective_retry_v4_corruption_root_cause_report.json"
    with open(report_path, 'w') as f:
        json.dump(comprehensive_report, f, indent=2)

    result = comprehensive_report.copy()
    result["artifacts"] = ["output/control/combine_v2_corrective_retry_v4_corruption_root_cause_report.json"]

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"Corrective Retry V4 Corruption Root Cause Report")
        print(f"Shot: {shot_id}")
        print(f"Root Cause: {root_cause}")
        print(f"Failure Code: {comprehensive_report['root_cause_analysis']['failure_code']}")
        print(f"Valid V4 Asset Recovered: {comprehensive_report['reconciliation_outcome']['valid_v4_asset_recovered']}")
        print(f"Next Allowed Action: {comprehensive_report['next_steps']['next_allowed_action']}")

    return 0


def combine_diagnose_corrective_retry_v4_workflow(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1821-1880 — Diagnose corrective retry V4 workflow for stub/fallback detection."""
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    timestamp = datetime.now(timezone.utc).isoformat()

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    # Load V4 artifacts
    implementation_package = _load_json(control_dir / "combine_v2_corrective_retry_v4_implementation_package.json")
    generation_trace = _load_json(control_dir / "combine_v2_corrective_retry_v4_generation_trace.json")
    workflow_audit = _load_json(control_dir / "combine_v2_corrective_retry_v4_workflow_submit_audit.json")
    submitted_workflow = _load_json(control_dir / f"{shot_id}_submitted_workflow.json")

    # Detect stub/fallback workflow
    stub_or_fallback_detected = False
    real_workflow_in_package = False
    workflow_node_count = 0
    saveimage_configured = False

    if workflow_audit:
        stub_or_fallback_detected = workflow_audit.get("stub_or_fallback_workflow_detected", False)
        real_workflow_in_package = workflow_audit.get("real_workflow_in_package", False)
        workflow_node_count = workflow_audit.get("workflow_node_count", 0)
        saveimage_configured = workflow_audit.get("saveimage_configured", False)

    # Check if submitted workflow is minimal/stub
    is_minimal_stub = False
    if submitted_workflow:
        node_count = len([k for k in submitted_workflow.keys() if k.isdigit()])
        if node_count <= 2:  # Only EmptyLatentImage or similar minimal nodes
            is_minimal_stub = True
            stub_or_fallback_detected = True

    # Check generation trace for stub flag
    if generation_trace:
        events = generation_trace.get("events", [])
        for event in events:
            if event.get("event") == "comfyui_execution" and event.get("stub"):
                stub_or_fallback_detected = True
                break

    # Create diagnosis report
    diagnosis = {
        "v4_workflow_diagnosis_executed": True,
        "previous_failure_code": "CORRECTIVE_RETRY_V4_WORKFLOW_SUBMIT_INVALID",
        "stub_or_fallback_workflow_detected": stub_or_fallback_detected,
        "fallback_workflow_allowed": False,
        "real_workflow_required": True,
        "real_workflow_binding_created": False,
        "real_workflow_binding_validated": False,
        "submit_blocked_until_real_workflow_bound": True,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": "corrective_retry_v4_real_workflow_binding_review_required",
        "shot_id": shot_id,
        "diagnosis_details": {
            "implementation_package_exists": bool(implementation_package),
            "generation_trace_exists": bool(generation_trace),
            "workflow_audit_exists": bool(workflow_audit),
            "submitted_workflow_exists": bool(submitted_workflow),
            "real_workflow_in_package": real_workflow_in_package,
            "workflow_node_count": workflow_node_count,
            "saveimage_configured": saveimage_configured,
            "is_minimal_stub": is_minimal_stub,
            "stub_generation_flagged": generation_trace.get("events", [{}])[0].get("stub", False) if generation_trace else False
        },
        "timestamp": timestamp
    }

    # Save diagnosis artifact
    diagnosis_path = control_dir / "combine_v2_corrective_retry_v4_workflow_diagnosis.json"
    with open(diagnosis_path, 'w') as f:
        json.dump(diagnosis, f, indent=2)

    if json_output:
        print(json.dumps(diagnosis, indent=2))
    else:
        print(f"V4 Workflow Diagnosis Executed: {diagnosis['v4_workflow_diagnosis_executed']}")
        print(f"Stub or Fallback Workflow Detected: {diagnosis['stub_or_fallback_workflow_detected']}")
        print(f"Real Workflow Required: {diagnosis['real_workflow_required']}")
        print(f"Submit Blocked Until Real Workflow Bound: {diagnosis['submit_blocked_until_real_workflow_bound']}")
        print(f"Next Allowed Action: {diagnosis['next_allowed_action']}")

    return 0


