def combine_preflight_corrective_retry_v4_real_workflow_submit(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-1881-2000 — Preflight real workflow submit for corrective retry V4."""
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    max_generations = args.max_generations
    json_output = args.json
    control_dir = project_root / "output" / "control"
    timestamp = datetime.now(timezone.utc).isoformat()

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    # Load validation
    validation = _load_json(control_dir / "combine_v2_corrective_retry_v4_generator_loader_fix_validation.json")

    if not validation:
        msg = "Error: Generator loader fix validation not found. Run combine-validate-corrective-retry-v4-generator-loader-fix first."
        if json_output:
            print(json.dumps({"status": "error", "message": msg}))
        else:
            print(msg)
        return 1

    # Load application
    application = _load_json(control_dir / "combine_v2_corrective_retry_v4_generator_loader_fix_application.json")

    # Load review
    review = _load_json(control_dir / "combine_v2_corrective_retry_v4_real_workflow_binding_review.json")

    # Load real workflow
    real_workflow_source = review.get("real_workflow_source_candidate", "none")
    real_workflow_path = control_dir / real_workflow_source if real_workflow_source != "none" else None

    if real_workflow_path and real_workflow_path.exists():
        real_workflow = _load_json(real_workflow_path)
    else:
        real_workflow = None

    # Preflight validation - check workflow would be valid for submit
    workflow_valid_for_submit = (
        real_workflow is not None and
        len([k for k in real_workflow.keys() if k.isdigit()]) > 2 and
        any("KSampler" in str(v) for v in real_workflow.values()) and
        any("SaveImage" in str(v) for v in real_workflow.values())
    )

    # Create preflight artifact
    preflight = {
        "real_workflow_preflight_executed": True,
        "preflight_type": "corrective_retry_v4_real_workflow_submit_preflight",
        "shot_id": shot_id,
        "max_generations": max_generations,
        "real_workflow_source": real_workflow_source or "none",
        "real_workflow_loaded": real_workflow is not None,
        "workflow_valid_for_submit": workflow_valid_for_submit,
        "workflow_node_count": len([k for k in real_workflow.keys() if k.isdigit()]) if real_workflow else 0,
        "workflow_has_ksampler": any("KSampler" in str(v) for v in real_workflow.values()) if real_workflow else False,
        "workflow_has_saveimage": any("SaveImage" in str(v) for v in real_workflow.values()) if real_workflow else False,
        "generator_loader_fix_applied": application.get("generator_loader_fix_applied", False) if application else False,
        "hardcoded_stub_generation_removed": application.get("hardcoded_stub_generation_removed", False) if application else False,
        "submit_blocks_without_valid_real_workflow": application.get("submit_blocks_without_valid_real_workflow", False) if application else False,
        "max_generations_one_preserved": application.get("max_generations_one_preserved", False) if application else False,
        "post_submit_validation_preserved": application.get("post_submit_validation_preserved", False) if application else False,
        "stub_asset_guard_preserved": application.get("stub_asset_guard_preserved", False) if application else False,
        "preflight_passed": workflow_valid_for_submit and validation.get("validation_passed", False),
        "dry_run_mode": True,
        "comfyui_submit_not_executed": True,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "visual_qa_executed": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": "corrective_retry_v4_generate_assets" if workflow_valid_for_submit else "corrective_retry_v4_generator_loader_fix_required",
        "timestamp": timestamp
    }

    # Save preflight artifact
    preflight_path = control_dir / "combine_v2_corrective_retry_v4_real_workflow_submit_preflight.json"
    with open(preflight_path, 'w') as f:
        json.dump(preflight, f, indent=2)

    # Update artifact index to preserve generation gate state
    artifact_index_path = control_dir / "artifact_index.json"
    artifact_index = _load_json(artifact_index_path)
    artifact_index["current_state"] = "corrective_retry_v4_generate_assets" if workflow_valid_for_submit else "corrective_retry_v4_generator_loader_fix_required"
    artifact_index["next_allowed_action"] = preflight["next_allowed_action"]
    artifact_index["real_workflow_preflight_executed"] = True
    artifact_index["preflight_passed"] = preflight["preflight_passed"]
    with open(artifact_index_path, 'w') as f:
        json.dump(artifact_index, f, indent=2)

    if json_output:
        print(json.dumps(preflight, indent=2))
    else:
        print(f"Real Workflow Preflight Executed: {preflight['real_workflow_preflight_executed']}")
        print(f"Preflight Passed: {preflight['preflight_passed']}")
        print(f"Workflow Valid For Submit: {preflight['workflow_valid_for_submit']}")
        print(f"Next Allowed Action: {preflight['next_allowed_action']}")

    return 0


def combine_preflight_corrective_retry_v4_visual_qa(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2481-2540 — Visual QA Preflight for Corrective Retry V4 canonical asset.

    Resolves the canonical V4 asset from outputs manifest and result review,
    validates all hard-boundary conditions, creates Visual QA input packet,
    and creates preflight artifact. Does NOT execute Visual QA verdict,
    operator review, generation, or assembly.

    Exit codes:
    - 0: preflight completed (check visual_qa_preflight_executed for status)
    - 1: fatal error (missing manifest, blocker condition)
    """
    import json
    import hashlib
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    assets_dir = project_root / "output" / "assets"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()

    CANONICAL_ASSET_RELATIVE = "output/assets/combine_v2_corrective_retry_v4_shot02_00001_.png"
    CANONICAL_ASSET_FILENAME = "combine_v2_corrective_retry_v4_shot02_00001_.png"
    OLD_SHOT01_MARKER = "shot01"

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    outputs_manifest = _load_json(control_dir / "combine_v2_corrective_retry_v4_outputs_manifest.json")
    result_review = _load_json(control_dir / "combine_v2_corrective_retry_v4_result_review.json")

    if not outputs_manifest:
        msg = {"blocker": "CANONICAL_ASSET_MISSING", "reason": "V4 outputs manifest not found"}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: CANONICAL_ASSET_MISSING — V4 outputs manifest not found")
        return 1

    if not result_review:
        msg = {"blocker": "CANONICAL_ASSET_MISSING", "reason": "V4 result review not found"}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: CANONICAL_ASSET_MISSING — V4 result review not found")
        return 1

    # Resolve canonical asset from manifest
    generated_assets = outputs_manifest.get("generated_assets", [])
    manifest_asset_count = len(generated_assets)
    manifest_sha256 = outputs_manifest.get("sha256", None)

    if manifest_asset_count == 0 or not generated_assets:
        msg = {"blocker": "CANONICAL_ASSET_MISSING", "reason": "No assets in V4 outputs manifest"}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: CANONICAL_ASSET_MISSING — No assets in V4 outputs manifest")
        return 1

    manifest_asset_path_str = generated_assets[0]

    # Validate canonical asset identity — must match expected V4 path, not shot01
    if OLD_SHOT01_MARKER in manifest_asset_path_str and "shot02" not in manifest_asset_path_str:
        msg = {"blocker": "OLD_SHOT01_ASSET_SELECTED", "manifest_asset": manifest_asset_path_str}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: OLD_SHOT01_ASSET_SELECTED — {manifest_asset_path_str}")
        return 1

    # Validate manifest asset matches canonical asset
    manifest_asset_matches_canonical = (
        CANONICAL_ASSET_FILENAME in manifest_asset_path_str
    )

    if not manifest_asset_matches_canonical:
        msg = {
            "blocker": "MANIFEST_CANONICAL_ASSET_MISMATCH",
            "manifest_asset": manifest_asset_path_str,
            "expected_canonical": CANONICAL_ASSET_RELATIVE,
        }
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: MANIFEST_CANONICAL_ASSET_MISMATCH")
        return 1

    # Resolve filesystem path
    if manifest_asset_path_str.startswith("output/"):
        canonical_asset_path = project_root / manifest_asset_path_str
    else:
        canonical_asset_path = project_root / "output" / manifest_asset_path_str

    # Asset existence check
    asset_exists = canonical_asset_path.exists()
    if not asset_exists:
        msg = {"blocker": "CANONICAL_ASSET_MISSING", "path": str(canonical_asset_path)}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: CANONICAL_ASSET_MISSING — {canonical_asset_path}")
        return 1

    # Asset readability check
    asset_readable = False
    asset_size_bytes = 0
    try:
        asset_size_bytes = canonical_asset_path.stat().st_size
        with open(canonical_asset_path, 'rb') as f:
            f.read(1)
        asset_readable = True
    except Exception:
        asset_readable = False

    if not asset_readable:
        msg = {"blocker": "CANONICAL_ASSET_UNREADABLE", "path": str(canonical_asset_path)}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: CANONICAL_ASSET_UNREADABLE")
        return 1

    asset_size_bytes_gt_1024 = asset_size_bytes > 1024

    # Stub asset detection: size <= 1024 or size == 8 bytes
    stub_asset_detected = asset_size_bytes <= 1024

    if stub_asset_detected:
        msg = {"blocker": "STUB_ASSET_DETECTED", "size_bytes": asset_size_bytes}
        if json_output:
            print(json.dumps(msg))
        else:
            print(f"BLOCKER: STUB_ASSET_DETECTED — size={asset_size_bytes}")
        return 1

    # Compute SHA256
    sha256_val = None
    try:
        h = hashlib.sha256()
        with open(canonical_asset_path, 'rb') as f:
            for chunk in iter(lambda: f.read(65536), b''):
                h.update(chunk)
        sha256_val = h.hexdigest()
    except Exception:
        sha256_val = None

    sha256_present = sha256_val is not None

    if not sha256_present:
        msg = {"blocker": "SHA256_MISSING"}
        if json_output:
            print(json.dumps(msg))
        else:
            print("BLOCKER: SHA256_MISSING")
        return 1

    # Validate manifest sha256 matches computed (if manifest has sha256)
    if manifest_sha256 and manifest_sha256 != sha256_val:
        msg = {"blocker": "MANIFEST_CANONICAL_ASSET_MISMATCH", "manifest_sha256": manifest_sha256, "computed_sha256": sha256_val}
        if json_output:
            print(json.dumps(msg))
        else:
            print("BLOCKER: MANIFEST_CANONICAL_ASSET_MISMATCH — SHA256 mismatch")
        return 1

    # Use manifest sha256 if present, else computed
    sha256_final = manifest_sha256 if manifest_sha256 else sha256_val

    # Image dimensions — attempt PIL, fallback to None
    width = None
    height = None
    try:
        from PIL import Image
        with Image.open(canonical_asset_path) as img:
            width, height = img.size
    except Exception:
        pass

    width_present = width is not None
    height_present = height is not None
    dimensions_valid = width_present and height_present and width > 0 and height > 0

    # Result review success branch check
    result_review_branch = result_review.get("branch_selected", None)
    result_review_success_branch_used = result_review_branch == "success"
    manifest_success_policy_passed = result_review.get("manifest_success_policy_passed", False)

    # Old shot01 asset guard
    old_shot01_asset_used = OLD_SHOT01_MARKER in manifest_asset_path_str and "shot02" not in manifest_asset_path_str
    stale_stub_asset_used = stub_asset_detected

    # Technical validation summary
    technical_validation = {
        "asset_exists": asset_exists,
        "asset_readable": asset_readable,
        "asset_size_bytes": asset_size_bytes,
        "asset_size_bytes_gt_1024": asset_size_bytes_gt_1024,
        "sha256_present": sha256_present,
        "sha256": sha256_final,
        "width_present": width_present,
        "height_present": height_present,
        "dimensions_valid": dimensions_valid,
        "stub_asset_detected": stub_asset_detected,
        "canonical_asset_used": manifest_asset_matches_canonical,
        "old_shot01_asset_used": old_shot01_asset_used,
        "stale_stub_asset_used": stale_stub_asset_used,
        "manifest_asset_matches_canonical_asset": manifest_asset_matches_canonical,
        "result_review_success_branch_used": result_review_success_branch_used,
    }

    # Operator visual concerns
    operator_visual_concerns = {
        "subject_too_small": True,
        "excessive_empty_space": True,
        "weak_composition": True,
        "shot_intent_not_satisfied": True,
        "prompt_scene_alignment_weak": True,
    }

    # Create Visual QA input packet
    visual_qa_input_packet = {
        "task_id": "RC-COMBINE-V2-2481-2540",
        "packet_type": "corrective_retry_v4_visual_qa_input_packet",
        "shot_id": shot_id,
        "canonical_asset_path": CANONICAL_ASSET_RELATIVE,
        "sha256": sha256_final,
        "file_size_bytes": asset_size_bytes,
        "width": width,
        "height": height,
        "source_manifest_path": "output/control/combine_v2_corrective_retry_v4_outputs_manifest.json",
        "source_result_review_path": "output/control/combine_v2_corrective_retry_v4_result_review.json",
        "technical_validation": technical_validation,
        "operator_visual_concerns": operator_visual_concerns,
        "known_visual_issues": list(operator_visual_concerns.keys()),
        "operator_visual_concerns_recorded": True,
        "full_visual_qa_verdict_executed": False,
        "operator_visual_review_executed": False,
        "generation_performed": False,
        "comfyui_execution": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "timestamp": timestamp,
    }

    input_packet_path = control_dir / "combine_v2_corrective_retry_v4_visual_qa_input_packet.json"
    with open(input_packet_path, 'w') as f:
        json.dump(visual_qa_input_packet, f, indent=2)

    # Create Visual QA preflight artifact
    preflight_artifact = {
        "task_id": "RC-COMBINE-V2-2481-2540",
        "stage": "corrective_retry_v4_visual_qa_preflight_required",
        "preflight_type": "corrective_retry_v4_visual_qa_preflight",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "visual_qa_preflight_executed": True,
        "full_visual_qa_verdict_executed": False,
        "operator_visual_review_executed": False,
        "generation_performed": False,
        "comfyui_execution": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "canonical_asset_path": CANONICAL_ASSET_RELATIVE,
        "sha256": sha256_final,
        "file_size_bytes": asset_size_bytes,
        "width": width,
        "height": height,
        "technical_validation": technical_validation,
        "operator_visual_concerns": operator_visual_concerns,
        "visual_qa_input_packet_path": "output/control/combine_v2_corrective_retry_v4_visual_qa_input_packet.json",
        "next_allowed_action": "corrective_retry_v4_visual_qa_required",
    }

    preflight_path = control_dir / "combine_v2_corrective_retry_v4_visual_qa_preflight.json"
    with open(preflight_path, 'w') as f:
        json.dump(preflight_artifact, f, indent=2)

    # Update artifact_index.json
    artifact_index_path = control_dir / "artifact_index.json"
    artifact_index = {}
    if artifact_index_path.exists():
        with open(artifact_index_path, 'r') as f:
            artifact_index = json.load(f)

    artifact_index["current_state"] = "corrective_retry_v4_visual_qa_preflight_required"
    artifact_index["next_allowed_action"] = "corrective_retry_v4_visual_qa_required"
    artifact_index["visual_qa_preflight_executed"] = True
    artifact_index["visual_qa_input_packet_created"] = True
    artifact_index["production_accepted"] = False
    artifact_index["downstream_blocked"] = True
    artifact_index["generation_performed"] = False
    artifact_index["comfyui_execution"] = False
    artifact_index["assembly_executed"] = False

    with open(artifact_index_path, 'w') as f:
        json.dump(artifact_index, f, indent=2)

    # Update episode_ledger.json
    ledger_path = control_dir / "episode_ledger.json"
    ledger = []
    if ledger_path.exists():
        with open(ledger_path, 'r') as f:
            try:
                data = json.load(f)
                ledger = data if isinstance(data, list) else data.get('events', data.get('records', []))
            except json.JSONDecodeError:
                ledger = []

    ledger.append({
        "task_id": "RC-COMBINE-V2-2481-2540",
        "event_type": "corrective_retry_v4_visual_qa_preflight_executed",
        "stage": "corrective_retry_v4_visual_qa_preflight_required",
        "shot_id": shot_id,
        "canonical_asset_path": CANONICAL_ASSET_RELATIVE,
        "sha256": sha256_final,
        "technical_validation_passed": (
            asset_exists and asset_readable and asset_size_bytes_gt_1024
            and sha256_present and not stub_asset_detected
            and manifest_asset_matches_canonical and result_review_success_branch_used
        ),
        "next_allowed_action": "corrective_retry_v4_visual_qa_required",
        "visual_qa_preflight_executed": True,
        "full_visual_qa_verdict_executed": False,
        "operator_visual_review_executed": False,
        "generation_performed": False,
        "comfyui_execution": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "timestamp": timestamp,
    })
    with open(ledger_path, 'w') as f:
        json.dump(ledger, f, indent=2)

    # Build result
    result = {
        "task_id": "RC-COMBINE-V2-2481-2540",
        "visual_qa_preflight_executed": True,
        "visual_qa_input_packet_created": True,
        "canonical_asset_used": manifest_asset_matches_canonical,
        "asset_path": CANONICAL_ASSET_RELATIVE,
        "asset_exists": asset_exists,
        "asset_readable": asset_readable,
        "asset_size_bytes_gt_1024": asset_size_bytes_gt_1024,
        "sha256_present": sha256_present,
        "sha256": sha256_final,
        "width_present": width_present,
        "height_present": height_present,
        "dimensions_valid": dimensions_valid,
        "stub_asset_detected": stub_asset_detected,
        "stale_stub_asset_used": stale_stub_asset_used,
        "old_shot01_asset_used": old_shot01_asset_used,
        "manifest_asset_matches_canonical_asset": manifest_asset_matches_canonical,
        "result_review_success_branch_used": result_review_success_branch_used,
        "operator_visual_concerns_recorded": True,
        "known_visual_issues": list(operator_visual_concerns.keys()),
        "full_visual_qa_verdict_executed": False,
        "operator_visual_review_executed": False,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "second_generation_attempted": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "current_state": "corrective_retry_v4_visual_qa_preflight_required",
        "next_allowed_action": "corrective_retry_v4_visual_qa_required",
        "artifacts": [
            "output/control/combine_v2_corrective_retry_v4_visual_qa_preflight.json",
            "output/control/combine_v2_corrective_retry_v4_visual_qa_input_packet.json",
        ],
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"V4 Visual QA Preflight Executed")
        print(f"Shot: {shot_id}")
        print(f"Canonical Asset: {CANONICAL_ASSET_RELATIVE}")
        print(f"Asset Exists: {asset_exists}")
        print(f"Asset Readable: {asset_readable}")
        print(f"SHA256: {sha256_final}")
        print(f"Stub Detected: {stub_asset_detected}")
        print(f"Next Allowed Action: corrective_retry_v4_visual_qa_required")

    return 0


def combine_run_corrective_retry_v4_visual_qa(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2541-2600 — Run Full Visual QA Verdict for Corrective Retry V4.

    Performs structured Visual QA on the V4 asset, generates a formal verdict,
    and routes to visual correction plan if the image fails.

    This command:
    - Reads the V4 Visual QA input packet and preflight
    - Validates the canonical asset
    - Performs visual checks (subject scale, composition, shot intent, etc.)
    - Creates Visual QA verdict artifact
    - Updates artifact_index.json and episode_ledger.json
    - Routes to corrective_retry_v4_visual_correction_plan_required if failed

    Exit codes:
    - 0: visual QA executed (verdict created)
    - 1: error or blocker
    """
    import json
    import hashlib
    from pathlib import Path
    from datetime import datetime, timezone
    from PIL import Image

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    assets_dir = project_root / "output" / "assets"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()
    task_id = "RC-COMBINE-V2-2541-2600"

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r') as f:
                return json.load(f)
        return {}

    # 1. Load input packet and preflight
    input_packet = _load_json(control_dir / "combine_v2_corrective_retry_v4_visual_qa_input_packet.json")
    preflight = _load_json(control_dir / "combine_v2_corrective_retry_v4_visual_qa_preflight.json")

    if not input_packet:
        msg = "Error: Visual QA input packet not found. Run combine-run-corrective-retry-v4-visual-qa-preflight first."
        if json_output:
            print(json.dumps({"status": "error", "message": msg}))
        else:
            print(msg)
        return 1

    # 2. Validate input packet
    input_packet_exists = True
    canonical_asset_path = input_packet.get("canonical_asset_path", "")
    canonical_asset_used = input_packet.get("canonical_asset_used", False)
    sha256_expected = input_packet.get("sha256", "")
    width_expected = input_packet.get("width", 0)
    height_expected = input_packet.get("height", 0)

    # Resolve asset path
    if canonical_asset_path.startswith("output/"):
        asset_path = project_root / canonical_asset_path
    else:
        asset_path = project_root / "output" / canonical_asset_path

    asset_exists = asset_path.exists()
    asset_readable = False
    sha256_actual = ""
    width = 0
    height = 0
    stub_asset_detected = False
    old_shot01_asset_used = False

    # Check if asset is old shot01 asset
    if "shot01" in str(asset_path).lower() and shot_id == "shot02":
        old_shot01_asset_used = True

    if asset_exists:
        try:
            # Check readability
            with open(asset_path, 'rb') as f:
                data = f.read()
                sha256_actual = hashlib.sha256(data).hexdigest()
            asset_readable = True

            # Get image dimensions
            with Image.open(asset_path) as img:
                width, height = img.size

            # Check for stub asset (unrealistic dimensions or tiny file)
            file_size = asset_path.stat().st_size
            if width < 100 or height < 100 or file_size < 1024:
                stub_asset_detected = True

        except Exception as e:
            asset_readable = False

    sha256_present = sha256_actual == sha256_expected and sha256_actual != ""

    # 3. Perform visual checks
    # Since operator already flagged visual failure, we preserve those concerns
    operator_concerns = input_packet.get("operator_visual_concerns", {})
    known_visual_issues = input_packet.get("known_visual_issues", [])

    # Required visual checks
    checks = {
        "subject_scale_check": {
            "status": "failed" if operator_concerns.get("subject_too_small", False) else "passed",
            "message": "Subject too small - operator concern" if operator_concerns.get("subject_too_small") else "Subject scale check passed"
        },
        "empty_space_check": {
            "status": "failed" if operator_concerns.get("excessive_empty_space", False) else "passed",
            "message": "Excessive empty space - operator concern" if operator_concerns.get("excessive_empty_space") else "Empty space check passed"
        },
        "composition_check": {
            "status": "failed" if operator_concerns.get("weak_composition", False) else "passed",
            "message": "Weak composition - operator concern" if operator_concerns.get("weak_composition") else "Composition check passed"
        },
        "shot_intent_alignment_check": {
            "status": "failed" if operator_concerns.get("shot_intent_not_satisfied", False) else "passed",
            "message": "Shot intent not satisfied - operator concern" if operator_concerns.get("shot_intent_not_satisfied") else "Shot intent alignment check passed"
        },
        "prompt_scene_alignment_check": {
            "status": "failed" if operator_concerns.get("prompt_scene_alignment_weak", False) else "passed",
            "message": "Prompt/scene alignment weak - operator concern" if operator_concerns.get("prompt_scene_alignment_weak") else "Prompt scene alignment check passed"
        },
        "technical_readability_check": {
            "status": "passed" if asset_readable else "failed",
            "message": "Asset readable" if asset_readable else "Asset not readable"
        },
        "production_quality_check": {
            "status": "failed" if known_visual_issues else "passed",
            "message": f"Production quality issues detected: {len(known_visual_issues)}" if known_visual_issues else "Production quality check passed"
        }
    }

    # 4. Determine verdict
    failed_reasons = []
    for check_name, check_result in checks.items():
        if check_result["status"] == "failed":
            failed_reasons.append(check_name)

    # Add operator concerns to failed reasons
    for concern in known_visual_issues:
        if concern not in failed_reasons:
            failed_reasons.append(concern)

    # Visual QA verdict: failed due to operator concerns
    visual_qa_verdict = "failed" if failed_reasons else "passed"

    # 5. Determine next action
    if visual_qa_verdict == "failed":
        next_allowed_action = "corrective_retry_v4_visual_correction_plan_required"
    else:
        # Even if passed, route to operator review for visual acceptance
        next_allowed_action = "operator_visual_review"

    # 6. Create Visual QA verdict artifact
    verdict_artifact = {
        "task_id": task_id,
        "stage": "corrective_retry_v4_visual_qa_required",
        "verdict_type": "corrective_retry_v4_visual_qa_verdict",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "visual_qa_executed": True,
        "visual_qa_verdict": visual_qa_verdict,
        "production_accepted": False,
        "asset_path": str(asset_path),
        "canonical_asset_path": canonical_asset_path,
        "sha256": sha256_actual,
        "sha256_expected": sha256_expected,
        "sha256_match": sha256_present,
        "width": width,
        "height": height,
        "file_size_bytes": asset_path.stat().st_size if asset_exists else 0,
        "checks": checks,
        "failed_reasons": failed_reasons,
        "operator_concerns_preserved": True,
        "known_visual_issues": known_visual_issues,
        "operator_visual_concerns": operator_concerns,
        "recommended_next_action": next_allowed_action,
        "requires_operator_review": True,
        "generation_performed": False,
        "comfyui_execution": False,
        "retry_attempted": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "input_validation": {
            "input_packet_exists": input_packet_exists,
            "canonical_asset_used": canonical_asset_used,
            "asset_exists": asset_exists,
            "asset_readable": asset_readable,
            "sha256_present": sha256_present,
            "stub_asset_detected": stub_asset_detected,
            "old_shot01_asset_used": old_shot01_asset_used
        }
    }

    verdict_path = control_dir / "combine_v2_corrective_retry_v4_visual_qa_verdict.json"
    with open(verdict_path, 'w') as f:
        json.dump(verdict_artifact, f, indent=2)

    # 7. Update artifact_index.json
    artifact_index_path = control_dir / "artifact_index.json"
    artifact_index = {}
    if artifact_index_path.exists():
        with open(artifact_index_path, 'r') as f:
            artifact_index = json.load(f)

    artifact_index["current_state"] = "corrective_retry_v4_visual_qa_required"
    artifact_index["next_allowed_action"] = next_allowed_action
    artifact_index["visual_qa_executed"] = True
    artifact_index["visual_qa_verdict"] = visual_qa_verdict
    artifact_index["production_accepted"] = False
    artifact_index["downstream_blocked"] = True
    artifact_index["generation_performed"] = False
    artifact_index["comfyui_execution"] = False
    artifact_index["retry_attempted"] = False
    artifact_index["assembly_executed"] = False

    with open(artifact_index_path, 'w') as f:
        json.dump(artifact_index, f, indent=2)

    # 8. Update episode_ledger.json
    ledger_path = control_dir / "episode_ledger.json"
    ledger = []
    if ledger_path.exists():
        with open(ledger_path, 'r') as f:
            try:
                data = json.load(f)
                ledger = data if isinstance(data, list) else data.get('events', data.get('records', []))
            except json.JSONDecodeError:
                ledger = []

    ledger.append({
        "task_id": task_id,
        "event_type": "corrective_retry_v4_visual_qa_executed",
        "stage": "corrective_retry_v4_visual_qa_required",
        "shot_id": shot_id,
        "visual_qa_verdict": visual_qa_verdict,
        "failed_reasons": failed_reasons,
        "operator_concerns_preserved": True,
        "production_accepted": False,
        "next_allowed_action": next_allowed_action,
        "generation_performed": False,
        "comfyui_execution": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "timestamp": timestamp,
    })
    with open(ledger_path, 'w') as f:
        json.dump(ledger, f, indent=2)

    # 9. Build result
    result = {
        "task_id": task_id,
        "visual_qa_executed": True,
        "visual_qa_input_packet_used": True,
        "canonical_asset_used": canonical_asset_used,
        "asset_exists": asset_exists,
        "asset_readable": asset_readable,
        "sha256_present": sha256_present,
        "sha256_match": sha256_present,
        "stub_asset_detected": stub_asset_detected,
        "old_shot01_asset_used": old_shot01_asset_used,
        "visual_qa_verdict": visual_qa_verdict,
        "failed_reasons": failed_reasons,
        "production_accepted": False,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "current_state": "corrective_retry_v4_visual_qa_required",
        "next_allowed_action": next_allowed_action,
        "requires_operator_review": True,
        "artifacts": [
            "output/control/combine_v2_corrective_retry_v4_visual_qa_verdict.json"
        ]
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"V4 Visual QA Verdict Executed")
        print(f"Shot: {shot_id}")
        print(f"Asset: {canonical_asset_path}")
        print(f"Asset Exists: {asset_exists}")
        print(f"Asset Readable: {asset_readable}")
        print(f"Visual QA Verdict: {visual_qa_verdict}")
        print(f"Failed Reasons: {failed_reasons}")
        print(f"Next Allowed Action: {next_allowed_action}")
        print(f"Production Accepted: False")

    return 0


def combine_build_corrective_retry_v4_visual_correction_plan(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2601-2660 — Build Corrective Retry V4 Visual Correction Plan.

    Creates a formal corrective visual plan from Visual QA failure reasons.
    Transforms failure reasons into actionable correction requirements.
    No generation, no ComfyUI submit, no retry execution.

    This command:
    - Reads V4 Visual QA verdict and input packet
    - Validates visual_qa_verdict=failed
    - Creates correction plan with failure-to-fix mapping
    - Creates operator review packet
    - Updates artifact_index.json and episode_ledger.json

    Exit codes:
    - 0: visual correction plan created successfully
    - 1: error or blocker (missing verdict, verdict not failed)
    """
    import json
    import hashlib
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    json_output = args.json
    control_dir = project_root / "output" / "control"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()
    task_id = "RC-COMBINE-V2-2601-2660"

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
        return {}

    # 1. Read required artifacts
    verdict_path = control_dir / "combine_v2_corrective_retry_v4_visual_qa_verdict.json"
    input_packet_path = control_dir / "combine_v2_corrective_retry_v4_visual_qa_input_packet.json"

    verdict = _load_json(verdict_path)
    input_packet = _load_json(input_packet_path)

    # 2. Validate required inputs
    if not verdict:
        msg = "Error: combine_v2_corrective_retry_v4_visual_qa_verdict.json not found. Run combine-run-corrective-retry-v4-visual-qa first."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "VISUAL_QA_VERDICT_MISSING", "message": msg}))
        else:
            print(msg)
        return 1

    if not input_packet:
        msg = "Error: combine_v2_corrective_retry_v4_visual_qa_input_packet.json not found. Run combine-preflight-corrective-retry-v4-visual-qa first."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "VISUAL_QA_INPUT_PACKET_MISSING", "message": msg}))
        else:
            print(msg)
        return 1

    # 3. Validate verdict is failed
    visual_qa_verdict = verdict.get("visual_qa_verdict", "")
    if visual_qa_verdict != "failed":
        msg = f"Error: Visual QA verdict is '{visual_qa_verdict}', not 'failed'. No correction plan needed."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "VISUAL_QA_VERDICT_NOT_FAILED", "verdict": visual_qa_verdict, "message": msg}))
        else:
            print(msg)
        return 1

    # 4. Get failed reasons
    failed_reasons = verdict.get("failed_reasons", [])
    known_visual_issues = verdict.get("known_visual_issues", [])
    operator_visual_concerns = verdict.get("operator_visual_concerns", {})

    if not failed_reasons and not known_visual_issues:
        msg = "Error: No failed_reasons or known_visual_issues found in verdict. Cannot create correction plan."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "FAILED_REASONS_MISSING", "message": msg}))
        else:
            print(msg)
        return 1

    # Combine all failure reasons
    all_failures = set(failed_reasons + known_visual_issues)

    # 5. Build failure-to-fix mapping
    correction_mapping = {}

    # subject_too_small
    if "subject_too_small" in all_failures or "subject_scale_check" in all_failures:
        correction_mapping["subject_too_small"] = {
            "failure": "Subject too small in frame",
            "corrective_actions": [
                "increase subject scale",
                "target subject height ratio: 0.40-0.60 of frame height",
                "reject if subject height ratio < 0.30",
                "prefer medium shot / medium-full shot",
                "avoid distant full-body landscape framing"
            ],
            "target_subject_height_ratio": "0.40-0.60",
            "minimum_subject_height_ratio": "0.30",
            "recommended_shot_type": "medium shot / medium-full shot",
            "avoid": "distant full-body landscape framing"
        }

    # excessive_empty_space
    if "excessive_empty_space" in all_failures or "empty_space_check" in all_failures:
        correction_mapping["excessive_empty_space"] = {
            "failure": "Excessive empty space - background dominates",
            "corrective_actions": [
                "reduce empty background dominance",
                "target empty-space ratio <= 0.45",
                "tighter crop/framing",
                "stronger foreground subject placement"
            ],
            "target_empty_space_ratio_max": "0.45",
            "recommended_framing": "tighter crop with foreground subject placement"
        }

    # weak_composition
    if "weak_composition" in all_failures or "composition_check" in all_failures:
        correction_mapping["weak_composition"] = {
            "failure": "Weak composition - flat or unbalanced",
            "corrective_actions": [
                "define composition target",
                "subject must be clear focal point",
                "rule-of-thirds or centered cinematic framing",
                "avoid flat empty background"
            ],
            "composition_target": "cinematic subject-focused framing",
            "techniques": ["rule-of-thirds", "centered cinematic", "focal point emphasis"],
            "avoid": "flat empty background"
        }

    # shot_intent_not_satisfied
    if "shot_intent_not_satisfied" in all_failures or "shot_intent_alignment_check" in all_failures:
        correction_mapping["shot_intent_not_satisfied"] = {
            "failure": "Shot intent not satisfied - frame does not match target",
            "corrective_actions": [
                "restate shot intent",
                "require prompt/graph to express shot02 target",
                "reject if frame reads as generic landscape/background"
            ],
            "shot_intent_restatement": "Character-focused shot with clear subject presence",
            "rejection_criteria": "generic landscape/background without clear subject"
        }

    # prompt_scene_alignment_weak
    if "prompt_scene_alignment_weak" in all_failures or "prompt_scene_alignment_check" in all_failures:
        correction_mapping["prompt_scene_alignment_weak"] = {
            "failure": "Prompt/scene alignment weak",
            "corrective_actions": [
                "strengthen prompt with explicit subject scale, position, camera distance, focal length/style",
                "include negative prompt constraints against tiny subject / empty background"
            ],
            "prompt_enhancements": [
                "explicit subject scale descriptors",
                "explicit subject position in frame",
                "camera distance specification",
                "focal length and style keywords"
            ],
            "negative_prompt_additions": [
                "tiny subject",
                "distant figure",
                "empty background",
                "landscape without subject"
            ]
        }

    # 6. Build retry prompt patch recommendations
    positive_prompt_additions = []
    negative_prompt_additions = []
    camera_framing_requirements = []
    subject_scale_requirements = []
    composition_requirements = []
    rejection_criteria = []

    if "subject_too_small" in correction_mapping:
        positive_prompt_additions.extend([
            "medium shot framing",
            "subject fills 40-60% of frame height",
            "close-up portrait composition",
            "subject prominent in foreground"
        ])
        subject_scale_requirements.extend([
            "subject height >= 40% of frame",
            "reject if subject < 30% of frame"
        ])
        rejection_criteria.append("subject smaller than 30% of frame height")

    if "excessive_empty_space" in correction_mapping:
        positive_prompt_additions.extend([
            "tight framing",
            "minimal background",
            "foreground subject emphasis"
        ])
        camera_framing_requirements.extend([
            "empty space <= 45% of frame",
            "subject dominant in composition"
        ])
        rejection_criteria.append("empty space exceeds 45% of frame")

    if "weak_composition" in correction_mapping:
        positive_prompt_additions.extend([
            "cinematic composition",
            "rule of thirds",
            "strong focal point",
            "professional photography"
        ])
        composition_requirements.extend([
            "subject is clear focal point",
            "balanced cinematic framing",
            "avoid flat backgrounds"
        ])

    if "shot_intent_not_satisfied" in correction_mapping:
        positive_prompt_additions.extend([
            "character-focused",
            "clear subject presence",
            "intentional shot framing"
        ])
        camera_framing_requirements.append("shot must express specific intent, not generic")

    if "prompt_scene_alignment_weak" in correction_mapping:
        positive_prompt_additions.extend([
            "explicit scale description",
            "defined camera distance",
            "specific focal length"
        ])
        negative_prompt_additions.extend([
            "tiny subject",
            "distant figure",
            "empty background",
            "landscape without subject",
            "small person in vast space"
        ])

    # 7. Build graph/workflow recommendations
    graph_recommendations = {
        "save_image_prefix": "combine_v2_corrective_retry_v4_shot02",
        "workflow_binding": "keep current canonical workflow binding unless review says otherwise",
        "optional_future_controls": [
            "crop/zoom node configuration",
            "regional conditioning for subject emphasis",
            "pose/layout control for composition",
            "depth control for subject separation"
        ],
        "graph_mutation_in_this_layer": False,
        "note": "No graph mutation in this layer - only metadata plan artifact is being built"
    }

    # 8. Create visual correction plan artifact
    visual_correction_plan = {
        "task_id": task_id,
        "stage": "corrective_retry_v4_visual_correction_plan_required",
        "plan_type": "corrective_retry_v4_visual_correction_plan",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "visual_qa_verdict_used": True,
        "visual_qa_verdict": visual_qa_verdict,
        "failed_reasons": list(all_failures),
        "correction_mapping": correction_mapping,
        "retry_prompt_patch": {
            "positive_prompt_additions": list(set(positive_prompt_additions)),
            "negative_prompt_additions": list(set(negative_prompt_additions)),
            "camera_framing_requirements": camera_framing_requirements,
            "subject_scale_requirements": subject_scale_requirements,
            "composition_requirements": composition_requirements,
            "rejection_criteria": rejection_criteria
        },
        "graph_recommendations": graph_recommendations,
        "canonical_asset_path": verdict.get("canonical_asset_path", ""),
        "sha256": verdict.get("sha256", ""),
        "generation_performed": False,
        "comfyui_execution": False,
        "retry_attempted": False,
        "workflow_mutated": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": "operator_retry_v4_visual_correction_plan_review_required"
    }

    plan_path = control_dir / "combine_v2_corrective_retry_v4_visual_correction_plan.json"
    with open(plan_path, 'w', encoding='utf-8') as f:
        json.dump(visual_correction_plan, f, indent=2)

    # 9. Create operator review packet
    operator_review_packet = {
        "task_id": task_id,
        "packet_type": "corrective_retry_v4_visual_correction_plan_review_packet",
        "stage": "operator_retry_v4_visual_correction_plan_review_required",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "visual_correction_plan_path": "output/control/combine_v2_corrective_retry_v4_visual_correction_plan.json",
        "operator_decision_required": True,
        "allowed_decisions": [
            "approve_visual_correction_plan",
            "request_visual_correction_plan_changes",
            "reject_visual_correction_plan"
        ],
        "decision_guidance": {
            "approve_visual_correction_plan": "Proceed with retry using the correction plan specifications",
            "request_visual_correction_plan_changes": "Request modifications to specific correction requirements",
            "reject_visual_correction_plan": "Reject the plan and route to manual review"
        },
        "correction_summary": {
            "failure_count": len(all_failures),
            "correction_areas": list(correction_mapping.keys()),
            "subject_scale_fixes": "subject_too_small" in correction_mapping,
            "empty_space_fixes": "excessive_empty_space" in correction_mapping,
            "composition_fixes": "weak_composition" in correction_mapping,
            "shot_intent_fixes": "shot_intent_not_satisfied" in correction_mapping,
            "prompt_alignment_fixes": "prompt_scene_alignment_weak" in correction_mapping
        },
        "generation_performed": False,
        "comfyui_execution": False,
        "retry_attempted": False,
        "workflow_mutated": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "next_allowed_action": "operator_retry_v4_visual_correction_plan_review_required"
    }

    review_packet_path = control_dir / "combine_v2_corrective_retry_v4_visual_correction_plan_review_packet.json"
    with open(review_packet_path, 'w', encoding='utf-8') as f:
        json.dump(operator_review_packet, f, indent=2)

    # 10. Update artifact_index.json
    artifact_index_path = control_dir / "artifact_index.json"
    artifact_index = _load_json(artifact_index_path)

    artifact_index["current_state"] = "corrective_retry_v4_visual_correction_plan_required"
    artifact_index["next_allowed_action"] = "operator_retry_v4_visual_correction_plan_review_required"
    artifact_index["visual_correction_plan_created"] = True
    artifact_index["visual_qa_verdict_used"] = True
    artifact_index["visual_qa_verdict"] = visual_qa_verdict
    artifact_index["production_accepted"] = False
    artifact_index["downstream_blocked"] = True
    artifact_index["generation_performed"] = False
    artifact_index["comfyui_execution"] = False
    artifact_index["retry_attempted"] = False
    artifact_index["assembly_executed"] = False

    # Add stage result
    if "stage_results" not in artifact_index:
        artifact_index["stage_results"] = []

    artifact_index["stage_results"].append({
        "stage": "corrective_retry_v4_visual_correction_plan_required",
        "success": True,
        "message": "Visual correction plan created from failed Visual QA verdict",
        "artifacts": [
            "combine_v2_corrective_retry_v4_visual_correction_plan.json",
            "combine_v2_corrective_retry_v4_visual_correction_plan_review_packet.json"
        ],
        "metadata": {
            "task_id": task_id,
            "visual_qa_verdict": visual_qa_verdict,
            "failed_reasons_count": len(all_failures),
            "correction_areas": list(correction_mapping.keys()),
            "next_allowed_action": "operator_retry_v4_visual_correction_plan_review_required",
            "generation_performed": False,
            "comfyui_execution": False,
            "retry_attempted": False,
            "workflow_mutated": False,
            "production_accepted": False
        },
        "timestamp": timestamp,
        "no_generation_performed": True
    })

    with open(artifact_index_path, 'w', encoding='utf-8') as f:
        json.dump(artifact_index, f, indent=2)

    # 11. Update episode_ledger.json
    ledger_path = control_dir / "episode_ledger.json"
    ledger = []
    if ledger_path.exists():
        with open(ledger_path, 'r', encoding='utf-8') as f:
            try:
                data = json.load(f)
                ledger = data if isinstance(data, list) else data.get('events', data.get('records', []))
            except json.JSONDecodeError:
                ledger = []

    ledger.append({
        "task_id": task_id,
        "event_type": "corrective_retry_v4_visual_correction_plan_created",
        "stage": "corrective_retry_v4_visual_correction_plan_required",
        "shot_id": shot_id,
        "visual_qa_verdict": visual_qa_verdict,
        "failed_reasons": list(all_failures),
        "correction_areas": list(correction_mapping.keys()),
        "visual_correction_plan_created": True,
        "operator_review_packet_created": True,
        "next_allowed_action": "operator_retry_v4_visual_correction_plan_review_required",
        "generation_performed": False,
        "comfyui_execution": False,
        "retry_attempted": False,
        "workflow_mutated": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "timestamp": timestamp
    })

    with open(ledger_path, 'w', encoding='utf-8') as f:
        json.dump(ledger, f, indent=2)

    # 12. Build result
    result = {
        "task_id": task_id,
        "status": "ok",
        "visual_correction_plan_created": True,
        "visual_qa_verdict_used": True,
        "visual_qa_verdict": visual_qa_verdict,
        "failed_reasons_mapped": True,
        "failed_reasons": list(all_failures),
        "correction_mapping": list(correction_mapping.keys()),
        "subject_scale_requirements_created": "subject_too_small" in correction_mapping,
        "target_subject_height_ratio": "0.40-0.60" if "subject_too_small" in correction_mapping else None,
        "minimum_subject_height_ratio": "0.30" if "subject_too_small" in correction_mapping else None,
        "empty_space_limit_created": "excessive_empty_space" in correction_mapping,
        "target_empty_space_ratio_max": "0.45" if "excessive_empty_space" in correction_mapping else None,
        "composition_requirements_created": "weak_composition" in correction_mapping,
        "shot_intent_requirements_created": "shot_intent_not_satisfied" in correction_mapping,
        "prompt_patch_recommendations_created": True,
        "operator_review_packet_created": True,
        "new_generation_performed": False,
        "new_comfyui_submit_executed": False,
        "retry_attempted": False,
        "workflow_mutated": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "current_state": "corrective_retry_v4_visual_correction_plan_required",
        "next_allowed_action": "operator_retry_v4_visual_correction_plan_review_required",
        "artifacts": [
            "output/control/combine_v2_corrective_retry_v4_visual_correction_plan.json",
            "output/control/combine_v2_corrective_retry_v4_visual_correction_plan_review_packet.json"
        ]
    }

    if json_output:
        print(json.dumps(result, indent=2))
    else:
        print(f"V4 Visual Correction Plan: CREATED")
        print(f"Shot: {shot_id}")
        print(f"Visual QA Verdict: {visual_qa_verdict}")
        print(f"Failed Reasons: {len(all_failures)}")
        print(f"Correction Areas: {list(correction_mapping.keys())}")
        print(f"Subject Scale Fixes: {'subject_too_small' in correction_mapping}")
        print(f"Empty Space Fixes: {'excessive_empty_space' in correction_mapping}")
        print(f"Composition Fixes: {'weak_composition' in correction_mapping}")
        print(f"Shot Intent Fixes: {'shot_intent_not_satisfied' in correction_mapping}")
        print(f"Prompt Alignment Fixes: {'prompt_scene_alignment_weak' in correction_mapping}")
        print(f"Operator Review Packet: CREATED")
        print(f"Next Allowed Action: operator_retry_v4_visual_correction_plan_review_required")
        print(f"Production Accepted: False")

    return 0


def combine_review_corrective_retry_v4_visual_correction_plan(args: argparse.Namespace) -> int:
    """RC-COMBINE-V2-2661-2720 — Review Corrective Retry V4 Visual Correction Plan.

    Operator review gate for the V4 visual correction plan.
    Allows operator to approve, request changes, or reject the correction plan.
    No generation, no ComfyUI submit, no retry execution.

    This command:
    - Reads visual correction plan and review packet
    - Validates current state requirements
    - Records operator decision
    - Updates artifact_index.json and episode_ledger.json
    - Sets next_allowed_action based on decision

    Exit codes:
    - 0: operator review recorded successfully
    - 1: error or blocker (missing plan, invalid state)
    """
    import json
    from pathlib import Path
    from datetime import datetime, timezone

    project_root = Path(args.project_root)
    shot_id = args.shot_id
    decision = args.decision
    reason = args.reason
    json_output = args.json
    control_dir = project_root / "output" / "control"
    control_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).isoformat()
    task_id = "RC-COMBINE-V2-2661-2720"

    def _load_json(path: Path):
        if path.exists():
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
        return {}

    # 1. Read required artifacts
    plan_path = control_dir / "combine_v2_corrective_retry_v4_visual_correction_plan.json"
    review_packet_path = control_dir / "combine_v2_corrective_retry_v4_visual_correction_plan_review_packet.json"
    artifact_index_path = control_dir / "artifact_index.json"

    visual_correction_plan = _load_json(plan_path)
    review_packet = _load_json(review_packet_path)
    artifact_index = _load_json(artifact_index_path)

    # 2. Validate required artifacts exist
    if not visual_correction_plan:
        msg = "Error: combine_v2_corrective_retry_v4_visual_correction_plan.json not found."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "VISUAL_CORRECTION_PLAN_MISSING", "message": msg}))
        else:
            print(msg)
        return 1

    if not review_packet:
        msg = "Error: combine_v2_corrective_retry_v4_visual_correction_plan_review_packet.json not found."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "REVIEW_PACKET_MISSING", "message": msg}))
        else:
            print(msg)
        return 1

    # 3. Validate current state
    current_state = artifact_index.get("current_state", "")
    next_allowed_action = artifact_index.get("next_allowed_action", "")

    valid_states = [
        "corrective_retry_v4_visual_correction_plan_required",
        "operator_retry_v4_visual_correction_plan_review_required"
    ]
    valid_next_actions = [
        "operator_retry_v4_visual_correction_plan_review_required"
    ]

    if current_state not in valid_states and next_allowed_action not in valid_next_actions:
        msg = f"Error: Invalid state. current_state={current_state}, next_allowed_action={next_allowed_action}. Expected: state in {valid_states} or next_allowed_action in {valid_next_actions}"
        if json_output:
            print(json.dumps({"status": "error", "blocker": "INVALID_STATE", "current_state": current_state, "next_allowed_action": next_allowed_action, "message": msg}))
        else:
            print(msg)
        return 1

    # 4. Validate production_accepted is false
    production_accepted = artifact_index.get("production_accepted", False)
    if production_accepted:
        msg = "Error: production_accepted is true. Cannot review visual correction plan after production acceptance."
        if json_output:
            print(json.dumps({"status": "error", "blocker": "PRODUCTION_ALREADY_ACCEPTED", "message": msg}))
        else:
            print(msg)
        return 1

    # 5. Determine next state based on decision
    if decision == "approve_visual_correction_plan":
        new_state = "operator_retry_v4_visual_correction_plan_review_required"
        new_next_allowed_action = "corrective_retry_v4_retry_implementation_plan_update_required"
        visual_correction_plan_approved = True
    elif decision == "request_visual_correction_plan_changes":
        new_state = "operator_retry_v4_visual_correction_plan_review_required"
        new_next_allowed_action = "corrective_retry_v4_visual_correction_plan_required"
        visual_correction_plan_approved = False
    elif decision == "reject_visual_correction_plan":
        new_state = "blocked_manual_review"
        new_next_allowed_action = "manual_review_required"
        visual_correction_plan_approved = False
    else:
        msg = f"Error: Invalid decision '{decision}'. Must be one of: approve_visual_correction_plan, request_visual_correction_plan_changes, reject_visual_correction_plan"
        if json_output:
            print(json.dumps({"status": "error", "blocker": "INVALID_DECISION", "message": msg}))
        else:
            print(msg)
        return 1

    # 6. Extract approved elements if decision is approve
    approved_failed_reasons = []
    approved_subject_scale_requirements = None
    approved_empty_space_requirements = None
    approved_composition_requirements = None
    approved_prompt_patch_recommendations = None

    if decision == "approve_visual_correction_plan":
        approved_failed_reasons = visual_correction_plan.get("failed_reasons", [])
        retry_prompt_patch = visual_correction_plan.get("retry_prompt_patch", {})
        approved_subject_scale_requirements = retry_prompt_patch.get("subject_scale_requirements", [])
        approved_empty_space_requirements = retry_prompt_patch.get("camera_framing_requirements", [])
        approved_composition_requirements = retry_prompt_patch.get("composition_requirements", [])
        approved_prompt_patch_recommendations = {
            "positive_prompt_additions": retry_prompt_patch.get("positive_prompt_additions", []),
            "negative_prompt_additions": retry_prompt_patch.get("negative_prompt_additions", [])
        }

    # 7. Create operator review artifact
    operator_review = {
        "task_id": task_id,
        "stage": "operator_retry_v4_visual_correction_plan_review_required",
        "review_type": "operator_retry_v4_visual_correction_plan_review",
        "shot_id": shot_id,
        "timestamp": timestamp,
        "operator_decision": decision,
        "visual_correction_plan_approved": visual_correction_plan_approved,
        "reason": reason,
        "approved_failed_reasons": approved_failed_reasons,
        "approved_subject_scale_requirements": approved_subject_scale_requirements,
        "approved_empty_space_requirements": approved_empty_space_requirements,
        "approved_composition_requirements": approved_composition_requirements,
        "approved_prompt_patch_recommendations": approved_prompt_patch_recommendations,
        "requested_changes": [] if decision != "request_visual_correction_plan_changes" else ["operator_requested_changes"],
        "generation_performed": False,
        "comfyui_execution": False,
        "retry_attempted": False,
        "workflow_mutated": False,
        "assembly_executed": False,
        "downstream_executed": False,
        "production_accepted": False,
        "current_state": new_state,
        "next_allowed_action": new_next_allowed_action
    }

    review_path = control_dir / "combine_v2_operator_retry_v4_visual_correction_plan_review.json"
    with open(review_path, 'w', encoding='utf-8') as f:
        json.dump(operator_review, f, indent=2)

    # 8. Update artifact_index.json
    artifact_index["current_state"] = new_state
    artifact_index["next_allowed_action"] = new_next_allowed_action
